sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var annualVolume = parseFloat(current.getValue('annual_volume')) || 0;
    var effortMinutes = parseFloat(current.getValue('effort_minutes')) || 0;
    var hourlyCost = parseFloat(current.getValue('hourly_cost')) || 0;

    var currentAnnualCost = 0;

    // 1. Calculate current_annual_cost
    if (annualVolume > 0 && effortMinutes > 0 && hourlyCost > 0) {
        currentAnnualCost = (annualVolume * (effortMinutes / 60)) * hourlyCost;
        current.setValue('current_annual_cost', currentAnnualCost);
    } else {
        // Fallback in case it was already calculated in a previous save
        currentAnnualCost = parseFloat(current.getValue('current_annual_cost')) || 0;
    }

    // 2. Calculate year_one_net_roi
    var expectedResolutionRate = parseFloat(current.getValue('expected_resolution_rate')) || 0;
    var buildEffort = parseFloat(current.getValue('build_effort')) || 0;
    var monthlyRunCost = parseFloat(current.getValue('monthly_run_cost')) || 0;

    // Gross Savings = Current Cost * (Resolution Rate %)
    var grossSavings = currentAnnualCost * (expectedResolutionRate / 100);

    // Net ROI = Savings minus One-Time Build Effort minus 12 Months OpEx
    var yearOneNetRoi = grossSavings - buildEffort - (monthlyRunCost * 12);

    current.setValue('year_one_net_roi', yearOneNetRoi);

})(current, previous);
